coverage=[]
def seg(s): return [s.split('-')[0],s.split('-')[1]]
def M(p,e,faces=None,views=None,names=None,planar=False):
 d={'points':p,'edges':[seg(x) if isinstance(x,str) else x for x in e],'views':{'neutral':{'label':'Условие и построение'},**(views or {})},'labelNames':list(p) if names is None else names}
 if faces:d['faces']=faces
 if planar:d['planar']=True
 return d

def V(label,*edges,polygon=None,points=None):
 d={'label':label}
 if edges:d['segments']=[seg(e) if isinstance(e,str) else e for e in edges]
 if polygon:d['polygon']=polygon
 if points:d['points']=points
 return d

def plane(m,z=0):
 p=m['points']; xs=[v[0] for v in p.values()];ys=[v[1] for v in p.values()];w=max(max(xs)-min(xs),max(ys)-min(ys),1)*.2
 for k,v in zip(['q1','q2','q3','q4'],[[min(xs)-w,min(ys)-w,z],[max(xs)+w,min(ys)-w,z],[max(xs)+w,max(ys)+w,z],[min(xs)-w,max(ys)+w,z]]):p[k]=v
 m.setdefault('faces',[]).append(['q1','q2','q3','q4']);return m

def proj(top,foot,h,ends):
 p={top:[0,0,h],foot:[0,0,0]};e=[f'{top}-{foot}'];views={'height':V('Перпендикуляр к плоскости',f'{top}-{foot}')}
 for name,(x,y) in ends.items():p[name]=[x,y,0];e +=[f'{top}-{name}',f'{foot}-{name}'];views[name]=V('Наклонная и её проекция',f'{top}-{name}',f'{foot}-{name}')
 return plane(M(p,e,views=views))

def cube(a=1,b=None,c=None):
 b=a if b is None else b;c=a if c is None else c
 p={'A':[0,0,0],'B':[a,0,0],'C':[a,b,0],'D':[0,b,0],'A1':[0,0,c],'B1':[a,0,c],'C1':[a,b,c],'D1':[0,b,c]}
 return M(p,['A-B','B-C','C-D','D-A','A1-B1','B1-C1','C1-D1','D1-A1','A-A1','B-B1','C-C1','D-D1'],[['A','B','C','D']])

def add(m,p=None,e=None,views=None,faces=None):
 if p:m['points'].update(p);m['labelNames']+=list(p)
 if e:m['edges'] +=[seg(x) if isinstance(x,str) else x for x in e]
 if views:m['views'].update(views)
 if faces:m.setdefault('faces',[]).extend(faces)
 return m

def S(title,text,why=PYTH,view='neutral',prompt=None):return {'title':title,'prompt':prompt or ('Как обосновать шаг «'+title.lower()+'»?'),'explanation':text,'justifications':[{'kind':'theorem','text':why}],'view':view}
