 page=(103 if n<=6 else 104 if n<=16 else 105 if n<=27 else 106 if n<=39 else 107) if par==10 else (108 if n<=2 else 109 if n<=8 else 110 if n<=18 else 111 if n<=28 else 112)
 pages=[page,page+1] if par==11 and n in [1,2] else [page]
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 lesson={'schemaVersion':1,'revision':1,'id':f'merz-ex-{par:02}-{n:03}','kind':'exercise','title':f'{par}.{n}. {title}','status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'main','chapter':'Глава 3. Перпендикулярность в пространстве','exercise':f'{par}.{n}','printedPages':pages,'pdfPages':[x+1 for x in pages]},'statement':{'text':statement,'goal':answer},'visualization':{'type':'scene3d','caption':caption,'model':m},'help':[{'id':'help-1','question':'С чего начать?','text':hint or steps[0]['explanation'],'theoryIds':[f'merz-theory-{par:02}']}],'steps':steps,'answer':{'mode':'manual','prompt':'Запиши результат и объясни ключевой переход. Доказательство проверяется преподавателем. Ожидаемый вывод: '+answer},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 path=f'ex-{par:02}-{n:03}.json';(OUT/path).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')
 coverage.append({'sourceEntryId':f'source-main-{par:02}-{n:03}','exercise':f'{par}.{n}','collection':'main','sourcePrintedPages':pages,'sourcePdfPages':[x+1 for x in pages],'requiredParts':[None],'authoredSourceSubparts':parts or [],'lessonIds':[lesson['id']],'lessonFiles':['stereo-course/merzlyak-10-base/lessons/'+path],'status':'authored-draft','review':'pending'})

