save(10,1,'Проекции диагонали грани','В кубе ABCDA₁B₁C₁D₁ укажите проекцию C₁D на плоскости: 1) ABC; 2) BB₁C; 3) AA₁B₁.',m,[S('Проецируй концы','Проекция отрезка определяется проекциями обоих концов. Из точки, уже лежащей в выбранной плоскости, она никуда не перемещается.',PR),S('1) Плоскость ABC','C₁ переходит в C по ребру C₁C; D остаётся D. Ответ: CD.',PR,'p1'),S('2) Плоскость BB₁C','C₁ остаётся C₁; D переходит в C по DC. Ответ: C₁C.',PR,'p2'),S('3) Плоскость AA₁B₁','C₁ переходит в B₁ по C₁B₁; D переходит в A по DA. Ответ: AB₁.',PR,'p3')],'1) CD; 2) C₁C; 3) AB₁.',['1','2','3'])
m=cube(3,2,2.5);add(m,e=['D-B1'],views={'p1':V('1: D₁B₁','D1-B1',polygon=['A1','B1','C1','D1']),'p2':V('2: DC₁','D-C1',polygon=['C','D','D1','C1']),'p3':V('3: DA₁','D-A1',polygon=['A','A1','D1','D'])})
save(10,2,'Проекции пространственной диагонали','В прямоугольном параллелепипеде ABCDA₁B₁C₁D₁ укажите проекцию DB₁ на плоскости: 1) A₁B₁C₁; 2) CDD₁; 3) AA₁D₁.',m,[S('Найди направления проецирования','Рёбра, перпендикулярные каждой выбранной грани, задают направления ортогонального проецирования.',PERP),S('1) Верхняя грань','D переходит в D₁, B₁ остаётся на месте. Проекция D₁B₁.',PR,'p1'),S('2) Грань CDD₁','D остаётся, B₁ переходит в C₁. Проекция DC₁.',PR,'p2'),S('3) Грань AA₁D₁','D остаётся, B₁ переходит в A₁. Проекция DA₁.',PR,'p3')],'1) D₁B₁; 2) DC₁; 3) DA₁.',['1','2','3'])
save(10,3,'Проекция наклонной 13','Из одной точки к плоскости проведены перпендикуляр длиной 12 см и наклонная длиной 13 см. Найдите длину её проекции.',proj('A','H',12,{'B':(5,0)}),[S('Выдели треугольник','Пусть AH=12 — перпендикуляр, AB=13 — наклонная. HB — искомая проекция; AH⊥HB.',PERP,'B'),S('Вычти квадрат катета','HB²=AB²−AH²=169−144=25.',PYTH,'B'),S('Возьми положительный корень','Длина HB=5 см.',PYTH,'B')],'5 см.')
save(10,4,'Расстояние до плоскости','Из A к плоскости α проведены перпендикуляр и наклонная длиной √7 см. Проекция наклонной равна √3 см. Найдите расстояние от A до α.',proj('A','H',2,{'B':(Q(3),0)}),[S('Обозначь расстояние','AH — перпендикуляр к α; HB=√3, AB=√7. Расстояние до плоскости равно AH.',PERP,'height'),S('Примени Пифагора','AH²=AB²−HB²=7−3=4.',PYTH,'B'),S('Найди длину','AH=2 см.',PYTH,'height')],'2 см.')
