save(10,6,'Наклонная под углом 60°','MH⊥α; MA,MB — наклонные. BH=6√6 см, MB=18 см, ∠MAH=60°. Найдите MA.',proj('M','H',6*Q(3),{'A':(6,0),'B':(0,6*Q(6))}),[S('Найди высоту','MH²=MB²−BH²=324−216=108, поэтому MH=6√3 см.',PYTH,'B'),S('Используй угол при A','В прямоугольном MAH величина sin60°=MH/MA.','Определение синуса.','A'),S('Вычисли MA','MA=6√3/(√3/2)=12 см.','Подстановка и вычисление.','A')],'12 см.')
for n,st,concl in [(7,'Докажите, что равные наклонные, проведённые к плоскости из одной точки, имеют равные проекции.','HB=HC.'),(8,'Докажите, что равные проекции двух наклонных, проведённых к плоскости из одной точки, означают равенство наклонных.','AB=AC.'),(16,'Докажите, что из двух наклонных к плоскости из одной точки большую проекцию имеет большая наклонная.','AB>AC ⇒ HB>HC.'),(17,'Докажите, что из двух наклонных к плоскости из одной точки больше та, проекция которой больше.','HB>HC ⇒ AB>AC.')]:
 m=proj('A','H',3,{'B':(4,0),'C':(0,4 if n<10 else 2)})
