 finish=('Из AB²=AC² следует HB²=HC² и HB=HC.' if n==7 else 'Из HB²=HC² следует AB²=AC² и AB=AC.' if n==8 else 'Из AB²>AC² следует HB²>HC², поэтому HB>HC.' if n==16 else 'Из HB²>HC² следует AB²>AC², поэтому AB>AC.')
