save(10,9,'Точка над центром описанной окружности','Точка принадлежит прямой, перпендикулярной плоскости многоугольника и проходящей через центр описанной окружности. Докажите её равноудалённость от вершин.',m,[S('Обозначь центр и точку','Пусть O — центр описанной окружности радиуса R, M лежит на перпендикуляре через O. Для любой вершины X: OX=R.','Радиусы одной окружности равны.','neutral'),S('Рассмотри внешнюю точку','Если M≠O, треугольник MOX прямоугольный и MX²=MO²+R². Правая часть не зависит от выбора вершины X.',PYTH,'height'),S('Учти точку в плоскости','Если M=O, все расстояния MX уже равны R. Итак, любая точка указанной прямой равноудалена от вершин.','Разбор обоих возможных случаев.')],'Все расстояния равны √(MO²+R²).',caption=CAP+' Квадрат иллюстрирует общий аргумент для любого вписанного многоугольника.')
def skewplanes(h):
 return M({'A':[-2,0,0],'P':[0,0,0],'B':[2,0,0],'C':[0,-2,h],'Q':[0,0,h],'D':[0,2,h],'a1':[-2,-2,0],'a2':[2,-2,0],'a3':[2,2,0],'a4':[-2,2,0],'b1':[-2,-2,h],'b2':[2,-2,h],'b3':[2,2,h],'b4':[-2,2,h]},['A-B','C-D','P-Q'],[['a1','a2','a3','a4'],['b1','b2','b3','b4']],{'perp':V('Общий перпендикуляр PQ','P-Q')},['P','Q'])
for n,h in [(10,4),(11,10)]:
 st=('Параллельные плоскости α,β находятся на расстоянии 4 см. Скрещивающиеся прямые m⊂α, n⊂β. Найдите расстояние между m и n.' if n==10 else 'Скрещивающиеся прямые лежат соответственно в параллельных плоскостях α,β и находятся на расстоянии 10 см. Найдите расстояние между плоскостями.')
 save(10,n,'Общий перпендикуляр между параллельными плоскостями',st,skewplanes(h),[S('Спроецируй одну прямую','Ортогональная проекция n на α — прямая n′, параллельная n. Прямые m и n′ непараллельны, иначе m∥n, что противоречит скрещиванию. Поэтому они пересекаются в P.',PR),S('Восстанови перпендикуляр','Прямая через P, перпендикулярная α, встречает n в Q. PQ перпендикулярен и α, и параллельной ей β, следовательно обеим прямым m,n.',PERP,'perp'),S('Приравняй расстояния',f'PQ — общий перпендикуляр прямых и перпендикуляр между плоскостями. Обе искомые величины равны {h} см.','Определения расстояний между скрещивающимися прямыми и параллельными плоскостями.','perp')],f'{h} см.',caption=CAP+' Для наглядности направления прямых на модели перпендикулярны; доказательство использует только их непараллельность.')
