save(10,14,'Перпендикуляр через вершину прямоугольного треугольника','В ABC: ∠ACB=90°, AB=10 см, ∠BAC=45°. Через A проведена AD⊥(ABC). Найдите расстояние между AD и BC.',m,[S('Проверь общий перпендикуляр','AC⊥BC по условию, AC⊥AD вследствие AD⊥(ABC). Концы A,C лежат на заданных прямых.',PERP,'perp'),S('Найди катет','AC=AB·cos45°=10/√2=5√2 см.','Косинус угла в прямоугольном треугольнике.','perp'),S('Запиши расстояние','Искомое расстояние равно AC=5√2 см.','Определение расстояния скрещивающихся прямых.','perp')],'5√2 см.')
save(10,15,'Каким может быть четырёхугольник оснований?','Из M к α проведены равные наклонные MA,MB,MC,MD. Могут ли A,B,C,D быть вершинами: 1) прямоугольника; 2) ромба; 3) прямоугольной трапеции; 4) равнобокой трапеции?',proj('M','O',3,{'A':(4,0),'B':(0,4),'C':(-4,0),'D':(0,-4)}),[S('Перейди к окружности','Основания равных наклонных равноудалены от проекции O точки M. Значит, ABCD должен быть вписанным четырёхугольником. Обратно: над центром любой описанной окружности можно взять M вне α и получить равные наклонные.',PYTH),S('1) Прямоугольник','Да: у любого прямоугольника есть описанная окружность, центр — пересечение диагоналей.','Диагонали прямоугольника равны и делятся пополам.'),S('2) Ромб','Да, если это квадрат. Вписанный ромб должен иметь противоположные углы одновременно равные и в сумме 180°, то есть все углы 90°. Для ромба, не являющегося квадратом, ответ отрицателен.','Сумма противоположных углов вписанного четырёхугольника равна 180°.'),S('3) Прямоугольная трапеция','Нет для трапеции с ровно одной парой параллельных сторон. Два её прямых угла вместе с условием вписанности вынудили бы два остальных угла быть прямыми; получился бы прямоугольник.','Признак вписанного четырёхугольника.'),S('4) Равнобокая трапеция','Да. Её противоположные углы дополняют друг друга до 180°, поэтому она вписывается в окружность.','Углы при каждом основании равнобокой трапеции равны.')],'1) да; 2) да, только квадрат; 3) нет; 4) да.',['1','2','3','4'],caption=CAP+' Показан квадрат: один пример, одновременно реализующий пункты 1 и 2. Пункты 3 и 4 обоснованы отдельно.')
save(10,18,'Отношение проекций 5:2','Из одной точки проведены наклонные 25 см и 17 см. Их проекции относятся как 5:2. Найдите расстояние от точки до плоскости.',proj('A','H',15,{'B':(20,0),'C':(0,8)}),[S('Обозначь проекции','Большей наклонной соответствует большая проекция: HB=5x, HC=2x, x>0.','Сравнение наклонных и их проекций.'),S('Исключи общую высоту','625−25x²=289−4x², откуда 21x²=336, x=4.',PYTH),S('Найди высоту','AH²=625−20²=225, поэтому AH=15 см.',PYTH,'height')],'15 см.')
save(10,19,'Сумма наклонных','Из одной точки проведены две наклонные с суммой длин 28 см; проекции равны 9 см и 5 см. Найдите эти наклонные.',proj('D','H',12,{'A':(9,0),'B':(0,5)}),[S('Обозначь длины','Пусть DA=x соответствует проекции 9, DB=y — проекции 5. x+y=28, x>y.','Сравнение наклонных.'),S('Вычти квадраты','x²−y²=9²−5²=56. Поэтому (x−y)·28=56 и x−y=2.',PYTH),S('Реши и найди высоту','x=15, y=13; DH=√(15²−9²)=12 см.',PYTH,'height')],'Наклонные 15 и 13 см.')
save(10,20,'Проверка совместимости условия','Из точки к плоскости проведены две наклонные, каждая образует с плоскостью угол 60°, а угол между наклонными равен 90°. Расстояние от точки до плоскости √3 см. Найдите расстояние между основаниями наклонных. Условие приведено как напечатано.',proj('A','H',Q(3),{'B':(1,0),'C':(-1,0)}),[S('Определи длины проекций','В каждом прямоугольном треугольнике высота AH=√3, угол наклонной с проекцией 60°. Поэтому HB=HC=AH/tan60°=1, AB=AC=AH/sin60°=2.','Тригонометрия прямоугольного треугольника.'),S('Используй угол 90°','Если ∠BAC=90°, по Пифагору BC=√(AB²+AC²)=2√2.',PYTH),S('Проверь неравенство треугольника','Однако основания B,C в плоскости удовлетворяют BC≤BH+HC=2. Равенство достигается, когда H лежит между B,C. Получено противоречие 2√2≤2.','Неравенство треугольника.'),S('Сформулируй корректный вывод','Условие несовместимо: такой конфигурации не существует. Число 2√2 получается из части условий, но не является ответом существующей геометрической задачи. Модель показывает предельный допустимый случай BC=2 с углом BAC=60°, а не требуемые 90°.','Противоречивое условие не задаёт геометрическую конфигурацию.')],'Такой конфигурации не существует: в напечатанном условии противоречие.',caption='Источник содержит несовместимые условия. Модель намеренно показывает только совместимую часть: высота √3, обе наклонные под 60° к плоскости, максимальное расстояние оснований 2. Угол между наклонными здесь 60°, а не 90°.')
save(10,21,'Перпендикулярные проекции','Две наклонные из одной точки образуют со своими проекциями углы 30°. Угол между проекциями 90°, расстояние между основаниями 6 см. Найдите наклонные и расстояние от точки до плоскости.',proj('A','O',Q(6),{'B':(3*Q(2),0),'C':(0,3*Q(2))}),[S('Сравни проекции','Одинаковая высота AO и равные углы 30° дают OB=OC=AO·√3.','Тангенс угла в прямоугольном треугольнике.'),S('Используй прямой угол в плоскости','В прямоугольном BOC: 36=OB²+OC²=6AO².',PYTH),S('Найди высоту и наклонные','AO=√6 см; AB=AC=AO/sin30°=2√6 см.',PYTH+' Определение синуса.','height')],'Наклонные 2√6 см каждая; расстояние √6 см.',parts=['inclines','plane-distance'])
# Equal distances to vertices.
def vertex_model(vertices,center,h,top='M'):
 p={**vertices,'O':[*center,0],top:[*center,h]}; names=list(vertices);e=[[names[i],names[(i+1)%len(names)]] for i in range(len(names))]+[[top,k] for k in names]+[[top,'O']]+[['O',k] for k in names]
 return M(p,e,[names],{'height':V('Высота над центром окружности',[top,'O']),'radius':V('Радиус описанной окружности',['O',names[0]])})
for n,a,h,r,statement,result in [(22,9,3,6,'Точка M удалена от каждой вершины правильного треугольника со стороной 9 см на 6 см. Найдите расстояние M до его плоскости.','3 см.'),(24,6,4,5,'Точка M равноудалена от вершин ABC и находится на расстоянии d от плоскости ABC. Найдите MA, если BC=a, ∠BAC=α.','√(d²+a²/(4sin²α)).')]:
 vm=vertex_model({'A':[0,a/Q(3),0],'B':[-a/2,-a/(2*Q(3)),0],'C':[a/2,-a/(2*Q(3)),0]},(0,0),h)
 ss=[S('Найди положение проекции','Пусть O — проекция M. Равные наклонные дают OA=OB=OC, значит O — центр описанной окружности.',PYTH,'radius')]
 if n==22:ss +=[S('Найди радиус','Для правильного треугольника R=a/√3=3√3 см.','Центр правильного треугольника делит медиану в отношении 2:1.','radius'),S('Найди высоту','MO²=MA²−R²=36−27=9; MO=3 см.',PYTH,'height')]
 else:ss +=[S('Вырази радиус через сторону и угол','По расширенной теореме синусов a/sinα=2R, поэтому R=a/(2sinα). Здесь 0<α<180°.','Расширенная теорема синусов.','radius'),S('Вернись к наклонной','MA²=MO²+OA²=d²+a²/(4sin²α). Длина MA — положительный квадратный корень.',PYTH,'height')]
 save(10,n,'Равноудалённость от вершин',statement,vm,ss,result,caption=CAP+(' Модель иллюстрирует случай a=6, α=60°, d=4; формула доказана для любого невырожденного ABC.' if n==24 else ''))
save(10,23,'Точка над прямоугольным треугольником','В прямоугольном ABC: ∠ACB=90°, AC=6 см, BC=8 см. Точка D удалена от каждой вершины на 13 см. Найдите расстояние D до плоскости ABC.',vertex_model({'A':[6,0,0],'B':[0,8,0],'C':[0,0,0]},(3,4),12,'D'),[S('Найди центр проекций','Проекция O точки D равноудалена от A,B,C, значит является центром описанной окружности. В прямоугольном треугольнике это середина гипотенузы.','Равные наклонные имеют равные проекции.','radius'),S('Найди радиус','AB=√(6²+8²)=10, R=AB/2=5 см.',PYTH,'radius'),S('Найди высоту','DO=√(13²−5²)=12 см.',PYTH,'height')],'12 см.')
save(10,25,'Радиус через площадь треугольника','В ABC: AB=BC=4√5 см, AC=8 см. Точка D равноудалена от вершин на 5√5 см. Найдите расстояние D до плоскости ABC.',vertex_model({'A':[-4,0,0],'B':[0,8,0],'C':[4,0,0]},(0,3),10,'D'),[S('Вычисли площадь','Высота из B равна √((4√5)²−4²)=8. Площадь S=8·8/2=32 см².',PYTH),S('Найди радиус описанной окружности','R=AB·BC·AC/(4S)=80·8/128=5 см. Проекция O равноудалённой точки D — центр этой окружности.','Формула R=abc/(4S); равные наклонные имеют равные проекции.','radius'),S('Найди расстояние до плоскости','DO=√((5√5)²−5²)=10 см.',PYTH,'height')],'10 см.')
