m=plane(M({'B':[0,0,0],'C':[12,0,16],'A':[12,15,16],'C1':[12,0,0],'A1':[12,15,0]},['B-C','C-A','A-B','C-C1','A-A1','B-C1','B-A1','C1-A1']))
save(10,27,'Проекция гипотенузы','ABC прямоугольный при C, BC=20 см, AC=15 см. Плоскость β проходит через B параллельно AC. Проекция BC на β равна 12 см. Найдите проекцию AB.',m,[S('Найди высоту C над β','CC₁=√(20²−12²)=16 см. Так как AC∥β, точки A и C имеют одинаковую высоту над β.',PYTH),S('Найди гипотенузу','AB=√(20²+15²)=25 см.',PYTH),S('Вычисли проекцию','AA₁=16; BA₁=√(25²−16²)=√369=3√41 см.',PYTH)],'3√41 см.')
