save(10,31,'Ось куба и ребро основания','O,O₁ — центры граней ABCD и A₁B₁C₁D₁ куба с ребром a. Найдите расстояние между CD и OO₁.',m,[S('Построй H','Возьмём середину H ребра CD. В квадрате OH⊥CD.','Симметрия квадрата.','perp'),S('Проверь перпендикуляр к оси','OO₁ параллельна боковым рёбрам и перпендикулярна основанию, поэтому OO₁⊥OH.',PERP,'perp'),S('Найди расстояние','OH=a/2 — расстояние между OO₁ и CD.','Расстояние центра квадрата до стороны.','perp')],'a/2.')
save(10,32,'Площадь по расстоянию между прямыми','Через вершину A треугольника ABC проведена прямая m⊥(ABC). Расстояние между m и BC равно 8 см, BC=10 см. Найдите площадь ABC.',M({'B':[0,0,0],'C':[10,0,0],'H':[4,0,0],'A':[4,8,0],'M':[4,8,7]},['A-B','A-C','B-C','A-H','A-M'],[['A','B','C']]),[S('Построй высоту треугольника','Опустим AH⊥BC. Поскольку m⊥(ABC), также AH⊥m.',PERP),S('Прочитай заданное расстояние','AH — общий перпендикуляр m и BC, поэтому AH=8 см.','Определение расстояния между скрещивающимися прямыми.'),S('Вычисли площадь','S=BC·AH/2=10·8/2=40 см².','Формула площади треугольника.')],'40 см².')
save(10,33,'Высота параллелограмма','Через B параллелограмма ABCD проведена прямая a⊥(ABCD). AB=6 см, площадь 72 см². Найдите расстояние между a и CD.',M({'A':[0,0,0],'B':[6,0,0],'C':[8,12,0],'D':[2,12,0],'H':[6,12,0],'M':[6,0,8]},['A-B','B-C','C-D','D-A','B-H','B-M'],[['A','B','C','D']]),[S('Построй общий перпендикуляр','Опустим BH⊥CD. Отрезок BH лежит в основании, поэтому BH⊥a и является общим перпендикуляром.',PERP),S('Вырази площадь','CD=AB=6. Высота к CD равна BH, поэтому 72=6·BH.','Площадь параллелограмма равна произведению основания на высоту.'),S('Найди расстояние','BH=12 см.','Решение линейного уравнения.')],'12 см.')
save(10,34,'Угол между наклонными','MH⊥α, MA и MB — наклонные; ∠MAH=30°, ∠MBH=45°, AH⊥BH. Найдите косинус угла AMB.',proj('M','H',1,{'A':(Q(3),0),'B':(0,1)}),[S('Вырази стороны через h','Положим MH=h>0. Тогда MA=2h, MB=h√2, AH=h√3, BH=h.','Тригонометрия прямоугольного треугольника.'),S('Найди AB','AH⊥BH, поэтому AB²=AH²+BH²=4h².',PYTH),S('Примени теорему косинусов','cos∠AMB=(MA²+MB²−AB²)/(2MA·MB)=(4h²+2h²−4h²)/(4√2h²)=√2/4.','Теорема косинусов.')],'√2/4.')
save(10,35,'Угол между проекциями','AO⊥α; AB,AC — наклонные, ∠ABO=∠ACO=45°. Косинус угла между наклонными равен 1/4. Найдите угол между их проекциями.',proj('A','O',1,{'B':(1,0),'C':(-.5,Q(3)/2)}),[S('Вырази равные длины','При AO=h получаем OB=OC=h, AB=AC=h√2.','Тригонометрия угла 45°.'),S('Найди основание BC','BC²=AB²+AC²−2AB·AC·(1/4)=4h²−h²=3h².','Теорема косинусов.'),S('Найди угол BOC','cos∠BOC=(h²+h²−3h²)/(2h²)=−1/2, поэтому ∠BOC=120°.','Теорема косинусов и значение косинуса.')],'120°.')
