save(10,39,'Сумма расстояний вершин до плоскости','Диагонали параллелограмма пересекаются в O. OM=1 см. Через M проведена плоскость α, не пересекающая параллелограмм. Докажите, что сумма расстояний от его вершин до α не превосходит 4 см.',m,[S('Учти одну сторону плоскости','Параллелограмм выпуклый и не пересекает α; все его вершины находятся с одной стороны. Поэтому их расстояния можно считать положительными высотами над α.','Если концы отрезка по разные стороны плоскости, отрезок пересекает её.'),S('Используй середины диагоналей','O — середина AC и BD. При ортогональном проецировании высота середины равна полусумме высот концов: d(A)+d(C)=2d(O), d(B)+d(D)=2d(O).','Параллельное проецирование сохраняет середину; линейность высоты на отрезке.'),S('Оцени общую сумму','Сумма равна 4d(O,α). Перпендикуляр из O к α не длиннее любого отрезка из O до точки α, в частности d(O,α)≤OM=1. Поэтому сумма≤4 см.','Перпендикуляр короче наклонной.')],'Сумма равна 4d(O,α)≤4 см.')
def circle(m,o,r,number=24):
 names=[]
 for i in range(number):
  k=f'circle{i}';m['points'][k]=[o[0]+r*math.cos(2*PI*i/number),o[1]+r*math.sin(2*PI*i/number),0];names.append(k)
 m['edges'] += [[names[i],names[(i+1)%number]] for i in range(number)];return m
