# §11: each line-foot is an actual orthogonal foot, possibly on an extension.
def foot(p,a,b):
 u=[b[i]-a[i] for i in range(3)];t=sum((p[i]-a[i])*u[i] for i in range(3))/sum(x*x for x in u);return [a[i]+t*u[i] for i in range(3)]
def polygon(verts,top,base,h,extra=None,edges=None):
 p=dict(verts);p[top]=[p[base][0],p[base][1],h];nn=list(verts);m=M(p,[[nn[i],nn[(i+1)%len(nn)]] for i in range(len(nn))]+[[top,base]], [nn]);
 if extra:add(m,p=extra)
 if edges:add(m,e=edges)
 return m

def foot_model(verts,top,base,h,side):
 m=polygon(verts,top,base,h);H=foot(m['points'][base],m['points'][side[0]],m['points'][side[1]]);add(m,p={'H':H},e=[[base,'H'],[top,'H']],views={'projection':V('Перпендикуляр в плоскости',[base,'H'],list(side)),'distance':V('Перпендикуляр из внешней точки',[top,'H'],[top,base])});return m

