save(11,10,'Расстояние до стороны произвольного треугольника','DA⊥(ABC), AB=10 см, AC=17 см, BC=21 см, расстояние D до плоскости ABC равно 15 см. Найдите расстояние от D до прямой BC.',m,[S('Построй общий прямоугольный треугольник','Пусть AH⊥BC. По теореме о трёх перпендикулярах DH⊥BC; искомое расстояние — DH.',TP,'distance'),S('Найди площадь основания','Полупериметр s=24. По Герону S=√(24·14·7·3)=84 см².','Формула Герона.'),S('Найди высоту AH','AH=2S/BC=168/21=8 см.','Формула площади треугольника.','projection'),S('Найди пространственное расстояние','DH=√(DA²+AH²)=√(15²+8²)=17 см.',PYTH,'distance')],'17 см.')
