save(11,13,'Тупой угол и высота над плоскостью','DA⊥(ABC), ∠ABC=120°, AB=14 см. Расстояние от D до прямой BC равно 2√43 см. Найдите расстояние D до плоскости ABC.',m,[S('Построй H на прямой BC','AH⊥BC. Из-за тупого угла B точка H лежит на продолжении BC за B. AH=AB·sin120°=7√3 см.','Синус угла и высота треугольника.','projection'),S('Определи пространственный перпендикуляр','DH⊥BC по теореме о трёх перпендикулярах. Поэтому DH=2√43 см.',TP,'distance'),S('Найди высоту DA','DA²=DH²−AH²=172−147=25, DA=5 см.',PYTH,'distance')],'5 см.')

def incenter_model(verts,o,h,top='M'):
 p=dict(verts);p.update(O=[o[0],o[1],0]);p[top]=[o[0],o[1],h];nn=list(verts);e=[[nn[i],nn[(i+1)%len(nn)]] for i in range(len(nn))]+[[top,'O']];views={'height':V('Расстояние до плоскости',[top,'O'])}
 for i in range(len(nn)):
  k=f'T{i+1}';p[k]=foot(p['O'],p[nn[i]],p[nn[(i+1)%len(nn)]]);e +=[['O',k],[top,k]];views[f'side{i+1}']=V('Радиус к стороне и искомый перпендикуляр',['O',k],[top,k])
 return M(p,e,[nn],views)

