save(11,27,'Главная диагональ перпендикулярна треугольной плоскости','В кубе ABCDA₁B₁C₁D₁ докажите A₁C⊥(DC₁B).',m,[S('Докажи A₁C⊥BD','Проекция A₁C на основание — AC. Диагонали квадрата AC и BD перпендикулярны, поэтому A₁C⊥BD.',TP,'projection'),S('Докажи A₁C⊥DC₁','Проекция A₁C на грань DCC₁D₁ — D₁C: A₁ проецируется в D₁, C остаётся. Диагонали D₁C и DC₁ этой квадратной грани перпендикулярны. Значит A₁C⊥DC₁.',TP),S('Примени признак','BD и DC₁ пересекаются в D и задают плоскость DC₁B. Прямая A₁C перпендикулярна обеим, следовательно перпендикулярна плоскости.','Признак перпендикулярности прямой и плоскости.','plane')],'A₁C⊥(DC₁B).')
m=M({'C':[0,0,0],'B':[4*Q(2),0,0],'A':[2*Q(2),2*Q(6),0],'S':[0,0,2],'M':[2*Q(2),0,0],'N':[3*Q(2),Q(6),0],'P':[4*Q(2)/3,0,2/3],'Q':[Q(2),Q(6)/3,0]},['A-B','B-C','C-A','S-A','S-B','S-C','S-M','C-N','P-Q'],[['A','B','C']],{'perp':V('Общий перпендикуляр PQ','P-Q','S-M','C-N')})
save(11,28,'Расстояние между SM и CN','ABC — равносторонний со стороной 4√2 см, SC⊥(ABC), SC=2 см. M — середина BC, N — середина AB. Найдите расстояние между SM и CN.',m,[S('Введи прямоугольные координаты','Пусть C=(0,0,0), B=(4√2,0,0), A=(2√2,2√6,0), S=(0,0,2). Тогда M=(2√2,0,0), N=(3√2,√6,0).','Координаты равностороннего треугольника и перпендикуляра к его плоскости.'),S('Построй концы перпендикуляра','Возьмём P∈SM, SP:PM=2:1, и Q∈CN, CQ:QN=1:2. Получаем P=(4√2/3,0,2/3), Q=(√2,√6/3,0).','Формула деления отрезка в заданном отношении.','perp'),S('Проверь два прямых угла','Направления SM=(2√2,0,−2), CN=(3√2,√6,0), PQ=(−√2/3,√6/3,−2/3). Скалярные произведения: PQ·SM=−4/3+4/3=0; PQ·CN=−2+2=0. Значит PQ перпендикулярен обеим прямым.','В ортонормированных координатах u⊥v ⇔ uₓvₓ+uᵧvᵧ+u_zv_z=0.','perp'),S('Вычисли длину','PQ=√(2/9+6/9+4/9)=2√3/3 см.','Формула расстояния в прямоугольных координатах.','perp')],'2√3/3 см.',hint='Здесь предложен дополнительный координатный способ. Нужны координаты середины/деления отрезка, формула длины и признак перпендикулярности через сумму произведений координат.')
m=M({'H':[0,0,0],'D':[0,15,0],'K':[15,0,0],'B':[5*Q(3),0,0]},['H-D','H-K','D-K','D-B'],planar=True)
save(11,29,'Наклонные к прямой','Из D вне прямой m проведены наклонные DK и DB, образующие с m углы 45° и 60°. DB=10√3 см. Найдите проекцию DK на m.',m,[S('Опусти общий перпендикуляр','Пусть DH⊥m. В прямоугольном DHB: DH=DB·sin60°=10√3·√3/2=15 см.','Синус в прямоугольном треугольнике.'),S('Используй угол 45°','В DHK: ∠DKH=45°, поэтому оба катета равны: HK=DH.','Равнобедренный прямоугольный треугольник.'),S('Запиши длину проекции','Проекция DK — HK, её длина 15 см.',PR)],'15 см.')
